/**
 * Preconditions, checked before any sample is taken.
 *
 * The harness's whole value is that a number can be traced to a run, so a tree
 * that cannot produce a trustworthy number must stop before it produces one
 * rather than after. Each check below corresponds to a real failure mode: a
 * missing generated file exits the CLI with a module error, and a `node_modules`
 * that belongs to another checkout produces a syntactically valid mixture of two
 * revisions that measures neither.
 *
 * The last failure mode is the dangerous one, because it does not look like an
 * error at all. `labz-apps/omp-leaderboard`'s `record-result.yml` clones the fork
 * fresh and runs the harness without an install, so this runs first there and
 * says what is missing instead of letting a sample time out.
 */

import { existsSync, readdirSync } from "node:fs";
import { isAbsolute, join, relative, sep } from "node:path";

import { REPO_ROOT } from "./provenance";

/** Generated by `bun install`'s `prepare` step. Gitignored, so a fresh clone lacks it. */
const GENERATED_TOOL_VIEWS = join(
	REPO_ROOT,
	"packages",
	"coding-agent",
	"src",
	"export",
	"html",
	"tool-views.generated.js",
);

/** The entry the interactive path spawns. */
const CLI_ENTRY = join(REPO_ROOT, "packages", "coding-agent", "src", "cli.ts");

/** Gitignored build output of the Rust addon; must be present to measure anything. */
const NATIVE_DIR = join(REPO_ROOT, "packages", "natives", "native");

/** Workspace package used to prove `@oh-my-pi/*` resolves to *this* checkout. */
const RESOLUTION_PROBE = "@oh-my-pi/pi-tui/package.json";

/** `packageManager` in the root package.json. */
const MINIMUM_BUN = [1, 4];

/** True when `target` is inside `root`, so a resolved path cannot be another checkout's. */
function isInside(root: string, target: string): boolean {
	const rel = relative(root, target);
	return rel !== "" && !rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel);
}

/** One unmet precondition: what is wrong, and the command that fixes it. */
interface Problem {
	what: string;
	fix: string;
}

/**
 * Verify the tree can produce a valid measurement.
 *
 * @throws Error listing every unmet precondition and its fix. Throws rather than
 * warns because every one of these produces a number that looks publishable and
 * is not.
 */
export function assertPreconditions(): void {
	const problems: Problem[] = [];

	const [major, minor] = Bun.version.split(".").map(part => Number.parseInt(part, 10));
	const versionOk =
		(major ?? 0) > MINIMUM_BUN[0] || ((major ?? 0) === MINIMUM_BUN[0] && (minor ?? 0) >= MINIMUM_BUN[1]);
	if (!versionOk) {
		problems.push({
			what: `bun ${MINIMUM_BUN.join(".")}+ is required (running ${Bun.version})`,
			fix: "install a newer bun; packageManager pins bun@>=1.4",
		});
	}

	if (!existsSync(CLI_ENTRY)) {
		problems.push({
			what: `CLI entry is missing: ${CLI_ENTRY}`,
			fix: "run this from a checkout of labz-apps/oh-my-pi",
		});
	}

	if (!existsSync(GENERATED_TOOL_VIEWS)) {
		problems.push({
			what: "tool-views.generated.js is missing (gitignored, produced by `bun install`)",
			fix: "bun install   # its `prepare` step generates the file",
		});
	}

	// The mixture-of-two-revisions check. A `node_modules` symlinked from another
	// worktree resolves `@oh-my-pi/*` there, and the CLI then runs a mixture of
	// this checkout's entry with another checkout's packages: it starts, it paints,
	// and the number is attributed to the wrong commit.
	let probeTarget: string | null = null;
	try {
		probeTarget = Bun.resolveSync(RESOLUTION_PROBE, REPO_ROOT);
	} catch {
		problems.push({
			what: `${RESOLUTION_PROBE} does not resolve from ${REPO_ROOT}`,
			fix: "bun install   # workspace links must point at this checkout",
		});
	}
	if (probeTarget !== null && !isInside(REPO_ROOT, probeTarget)) {
		problems.push({
			what: `${RESOLUTION_PROBE} resolves to ${probeTarget}, which is outside this checkout`,
			fix: "delete node_modules and run `bun install` here; a symlinked node_modules measures another checkout",
		});
	}

	if (!nativesReady()) {
		problems.push({
			what:
				"the Rust native addons are not built, so the app exits 1 during module init " +
				"(Cannot find module '@oh-my-pi/pi-natives/path') and never paints",
			fix: "bun --cwd=packages/natives run build",
		});
	}

	if (problems.length > 0) {
		throw new Error(
			`benchmark harness preconditions not met (${problems.length}):\n` +
				problems.map(problem => `  - ${problem.what}\n    fix: ${problem.fix}`).join("\n"),
		);
	}
}

/**
 * True when the Rust native addons are present and loadable in this checkout.
 *
 * Not a soft requirement. Without a built `pi_natives.*.node` the subpath export
 * fails to resolve and the app exits 1 during module init, before any paint:
 *
 *   error: Cannot find module '@oh-my-pi/pi-natives/path'
 *          from 'packages/utils/src/dirs.ts'
 *
 * So a checkout without them produces no interactive frame at all, and every
 * sample would burn its whole timeout and then report `no-paint`, which points at
 * the TUI instead of at the missing build.
 */
function nativesReady(): boolean {
	if (!existsSync(NATIVE_DIR)) return false;
	const built = readdirSync(NATIVE_DIR).some(file => file.endsWith(".node"));
	if (!built) return false;
	try {
		// The exact specifier the app itself fails on, so a built-but-unloadable
		// addon (wrong architecture) is caught here rather than per sample.
		Bun.resolveSync("@oh-my-pi/pi-natives/path", REPO_ROOT);
		return true;
	} catch {
		return false;
	}
}

/**
 * Non-fatal advisories, printed once before sampling.
 *
 * Reserved for conditions that change how a number should be read rather than
 * whether it can be measured at all.
 */
export function preflightWarnings(): string[] {
	const warnings: string[] = [];
	if (!nativesReady()) {
		warnings.push(
			"packages/natives/native is absent; both series need the Rust addons, so this run will not produce a frame",
		);
	}
	return warnings;
}
